//! Exports the forwarder table generated by `tools/kernelx_exports.py`
//! (`runtime/kernelx/kernelx_forwarders.inc`), so this cdylib forwards the same 2,661 functions
//! to kernel32/kernelbase as the C++ kernelx.dll (see `anyxboxx-forwarders` for how).

const TABLE: &str = "../../runtime/kernelx/kernelx_forwarders.inc";

fn main() {
    println!("cargo:rerun-if-changed={TABLE}");
    let text = std::fs::read_to_string(TABLE)
        .unwrap_or_else(|e| panic!("{TABLE}: {e} (generated by tools/kernelx_exports.py)"));
    let forwarders =
        anyxboxx_forwarders::parse_pragmas(&text).unwrap_or_else(|e| panic!("{TABLE}: {e}"));
    assert!(!forwarders.is_empty(), "{TABLE}: no forwarder found");
    println!("cargo:rustc-env=KERNELX_FORWARDERS={}", forwarders.len());
    anyxboxx_forwarders::link("kernelx", &forwarders, &[]);
}
